// Verify Webhook Signature & Security Token
const headers = $input.first().json.headers || {};
const payload = $input.first().json.body || $input.first().json;
const webhookSecret = process.env.WEBHOOK_SECRET_KEY || 'default_secret_key';
const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];

if (providedSecret && providedSecret !== webhookSecret) {
  throw new Error('Unauthorized: Invalid webhook secret token.');
}

// Payload Validation
if (!payload.post_id || !payload.child_name || !payload.last_seen_location) {
  throw new Error('Invalid Payload: post_id, child_name, and last_seen_location are required.');
}

// Normalize & Sanitize Data
const normalizedData = {
  post_id: payload.post_id,
  child_name: payload.child_name,
  age: payload.age || 'Unknown',
  gender: payload.gender || 'Not specified',
  last_seen_location: payload.last_seen_location,
  last_seen_date: payload.last_seen_date ? new Date(payload.last_seen_date).toISOString() : new Date().toISOString(),
  photo_url: payload.photo_url || 'https://kidnap-children.org/images/default_missing.png',
  contact_phone: payload.contact_phone || 'Emergency Services (911)',
  reporter_email: payload.reporter_email || '',
  recipient_emails: payload.recipient_emails || [process.env.DEFAULT_ALERT_EMAIL || 'alerts@kidnap-children.org'],
  recipient_phones: payload.recipient_phones || [process.env.DEFAULT_ALERT_SMS || '+1234567890'],
  urgency_level: payload.urgency_level || 'CRITICAL',
  description: payload.description || 'No additional details provided.',
  post_url: payload.post_url || `https://kidnap-children.org/posts/${payload.post_id}`,
  timestamp: new Date().toISOString()
};

return [{ json: normalizedData }];

