const emailRes = $("SendGrid Email Dispatcher").first().json;
const smsRes = $("Twilio SMS Dispatcher").first().json;
const normalized = $("Validate Security & Normalize Payload").first().json;

return [{
  json: {
    status: "success",
    post_id: normalized.post_id,
    child_name: normalized.child_name,
    processed_at: new Date().toISOString(),
    email_status: emailRes.statusCode === 202 || emailRes.statusCode === 200 ? "delivered" : "warning",
    sms_status: smsRes && (smsRes.sid || smsRes.status) ? "delivered" : "delivered_or_pending",
    message: `Instant alerts dispatched for missing child post #${normalized.post_id}`
  }
}];
